class Solution {
public:
    int minimumCost(std::vector<int>& start, std::vector<int>& target, std::vector<std::vector<int>>& specialRoads) {
        std::vector<std::vector<int>> filtered;
        for (const auto& r : specialRoads) {
            if (r[4] < std::abs(r[0] - r[2]) + std::abs(r[1] - r[3])) {
                filtered.push_back(r);
            }
        }
        int n = filtered.size();
        std::vector<int> dist(n, 1e9);
        std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<>> pq;
        int ans = std::abs(start[0] - target[0]) + std::abs(start[1] - target[1]);
        for (int i = 0; i < n; i++) {
            dist[i] = std::abs(start[0] - filtered[i][0]) + std::abs(start[1] - filtered[i][1]) + filtered[i][4];
            pq.push({dist[i], i});
        }
        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d > dist[u]) continue;
            ans = std::min(ans, d + std::abs(target[0] - filtered[u][2]) + std::abs(target[1] - filtered[u][3]));
            for (int v = 0; v < n; v++) {
                int cost = d + std::abs(filtered[u][2] - filtered[v][0]) + std::abs(filtered[u][3] - filtered[v][1]) + filtered[v][4];
                if (cost < dist[v]) {
                    dist[v] = cost;
                    pq.push({dist[v], v});
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int minimumCost(int[] start, int[] target, int[][] specialRoads) {
        List<int[]> filtered = new ArrayList<>();
        for (int[] r : specialRoads) {
            if (r[4] < Math.abs(r[0] - r[2]) + Math.abs(r[1] - r[3])) {
                filtered.add(r);
            }
        }
        int n = filtered.size();
        int[] dist = new int[n];
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        int ans = Math.abs(start[0] - target[0]) + Math.abs(start[1] - target[1]);
        for (int i = 0; i < n; i++) {
            int[] r = filtered.get(i);
            dist[i] = Math.abs(start[0] - r[0]) + Math.abs(start[1] - r[1]) + r[4];
            pq.offer(new int[]{dist[i], i});
        }
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int d = cur[0], u = cur[1];
            if (d > dist[u]) continue;
            int[] rU = filtered.get(u);
            ans = Math.min(ans, d + Math.abs(target[0] - rU[2]) + Math.abs(target[1] - rU[3]));
            for (int v = 0; v < n; v++) {
                int[] rV = filtered.get(v);
                int cost = d + Math.abs(rU[2] - rV[0]) + Math.abs(rU[3] - rV[1]) + rV[4];
                if (cost < dist[v]) {
                    dist[v] = cost;
                    pq.offer(new int[]{dist[v], v});
                }
            }
        }
        return ans;
    }
}

var minimumCost = function(start, target, specialRoads) {
    const filtered = specialRoads.filter(r => r[4] < Math.abs(r[0] - r[2]) + Math.abs(r[1] - r[3]));
    const n = filtered.length;
    const dist = new Array(n);
    let ans = Math.abs(start[0] - target[0]) + Math.abs(start[1] - target[1]);
    for (let i = 0; i < n; i++) {
        const r = filtered[i];
        dist[i] = Math.abs(start[0] - r[0]) + Math.abs(start[1] - r[1]) + r[4];
    }
    const visited = new Set();
    for (let iter = 0; iter < n; iter++) {
        let u = -1;
        for (let i = 0; i < n; i++) {
            if (!visited.has(i) && (u === -1 || dist[i] < dist[u])) {
                u = i;
            }
        }
        if (u === -1 || dist[u] === Infinity) break;
        visited.add(u);
        const rU = filtered[u];
        ans = Math.min(ans, dist[u] + Math.abs(target[0] - rU[2]) + Math.abs(target[1] - rU[3]));
        for (let v = 0; v < n; v++) {
            const rV = filtered[v];
            const cost = dist[u] + Math.abs(rU[2] - rV[0]) + Math.abs(rU[3] - rV[1]) + rV[4];
            if (cost < dist[v]) {
                dist[v] = cost;
            }
        }
    }
    return ans;
};
